1	/**
2	 * The write edge: text lines in, validated Samples out, buffered until drained.
3	 */
4	
5	import type { Sample } from "./validate.ts";
6	import { ValidationError, validateSample } from "./validate.ts";
7	
8	/**
9	 * Parse one wire line into a Sample.
10	 *
11	 * Wire format is three whitespace-separated fields: `<series> <value> <at>`.
12	 * A trailing timestamp may be omitted, in which case `fallbackAt` is used.
13	 */
14	export function parseSample(line: string, fallbackAt?: number): Sample {
15	  const fields = line.trim().split(/\s+/);
16	  if (fields.length < 2 || fields.length > 3) {
17	    throw new ValidationError(
18	      "line",
19	      `expected "<series> <value> [<at>]", got ${fields.length} field(s)`,
20	    );
21	  }
22	  const [series, rawValue, rawAt] = fields;
23	
24	  const at = rawAt === undefined ? fallbackAt : Number(rawAt);
25	  if (at === undefined) {
26	    throw new ValidationError("at", "omitted, and no fallback timestamp given");
27	  }
28	
29	  return validateSample({ series, value: Number(rawValue), at });
30	}
31	
32	/**
33	 * A bounded FIFO buffer between the wire and the store.
34	 *
35	 * Overflow drops the *oldest* sample, not the newest: under sustained pressure
36	 * a recent picture beats a stale one.
37	 */
38	export class IngestQueue {
39	  private buffer: Sample[] = [];
40	  private dropped = 0;
41	  private readonly capacity: number;
42	
43	  constructor(capacity: number) {
44	    if (!Number.isInteger(capacity) || capacity <= 0) {
45	      throw new RangeError("capacity must be a positive integer");
46	    }
47	    this.capacity = capacity;
48	  }
49	
50	  push(sample: Sample): void {
51	    this.buffer.push(sample);
52	    while (this.buffer.length > this.capacity) {
53	      this.buffer.shift();
54	      this.dropped += 1;
55	    }
56	  }
57	
58	  /** Take everything buffered so far, leaving the queue empty. */
59	  drain(): Sample[] {
60	    const taken = this.buffer;
61	    this.buffer = [];
62	    return taken;
63	  }
64	
65	  size(): number {
66	    return this.buffer.length;
67	  }
68	
69	  /** How many samples overflow has discarded since construction. */
70	  droppedCount(): number {
71	    return this.dropped;
72	  }
73	}
74

1	import assert from "node:assert/strict";
2	import { describe, it } from "node:test";
3	
4	import { IngestQueue, parseSample } from "../src/ingest.ts";
5	import { createService } from "../src/index.ts";
6	import { ValidationError } from "../src/validate.ts";
7	
8	describe("parseSample", () => {
9	  it("parses the three-field wire form", () => {
10	    assert.deepEqual(parseSample("cpu.load 0.5 1000"), {
11	      series: "cpu.load",
12	      value: 0.5,
13	      at: 1000,
14	    });
15	  });
16	
17	  it("falls back to the supplied timestamp when `at` is omitted", () => {
18	    assert.deepEqual(parseSample("cpu.load 0.5", 7000), {
19	      series: "cpu.load",
20	      value: 0.5,
21	      at: 7000,
22	    });
23	  });
24	
25	  it("rejects a line with too many fields", () => {
26	    assert.throws(() => parseSample("cpu.load 1 2 3"), ValidationError);
27	  });
28	
29	  it("rejects an omitted timestamp with no fallback", () => {
30	    assert.throws(() => parseSample("cpu.load 1"), /at:/);
31	  });
32	});
33	
34	describe("IngestQueue", () => {
35	  it("drains what was pushed, in order", () => {
36	    const queue = new IngestQueue(4);
37	    queue.push({ series: "a", value: 1, at: 1 });
38	    queue.push({ series: "a", value: 2, at: 2 });
39	    assert.equal(queue.size(), 2);
40	    assert.deepEqual(
41	      queue.drain().map((s) => s.value),
42	      [1, 2],
43	    );
44	    assert.equal(queue.size(), 0);
45	  });
46	
47	  it("drops the oldest sample on overflow", () => {
48	    const queue = new IngestQueue(2);
49	    for (const value of [1, 2, 3]) {
50	      queue.push({ series: "a", value, at: value });
51	    }
52	    assert.deepEqual(
53	      queue.drain().map((s) => s.value),
54	      [2, 3],
55	    );
56	    assert.equal(queue.droppedCount(), 1);
57	  });
58	
59	  it("refuses a non-positive capacity", () => {
60	    assert.throws(() => new IngestQueue(0), RangeError);
61	  });
62	});
63	
64	describe("the ingest path", () => {
65	  it("buffers a posted sample and lands it on the next tick", () => {
66	    const service = createService(
67	      { windowMs: 1_000, retentionMs: 60_000, maxSamples: 4 },
68	      { now: () => 1_000 },
69	    );
70	
71	    const reply = service.router.dispatch("POST", "/samples", "cpu.load 0.5 1000");
72	    assert.equal(reply.status, 202);
73	    assert.deepEqual(
74	      service.store.series(),
75	      [],
76	      "a posted sample is buffered, not stored — the store is only current after a tick",
77	    );
78	
79	    service.tick();
80	    assert.deepEqual(service.store.series(), ["cpu.load"]);
81	  });
82	});
